def parse_fixture(self, name: str) -> dict:
        path = self.FIXTURES / name
        source = path.read_bytes()
        return parse_file(
            {"commit": "cpp-parser-fixture"},
            {"id": f"file-{name}", "path": name, "blob": hashlib.sha1(source).hexdigest(), "language": "cpp"},
            source,
        )

def _write_json(path: Path, value: dict) -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(value, ensure_ascii=False), encoding="utf-8")

def _file(path: str, blob: str) -> dict:
        return {
            "file": {
                "path": path,
                "language": "python",
                "blob": blob,
                "size": 10,
                "mode": "100644",
            },
            "parse": {"status": "passed"},
        }

def _entity(entity_id: str, path: str, qualified_name: str) -> dict:
        return {
            "id": entity_id,
            "kind": "function",
            "language": "python",
            "path": path,
            "name": qualified_name,
            "qualified_name": qualified_name,
        }

